/** Polls every 10 ms, for half a second at most, until the check holds. */
export async function eventually(check: () => boolean): Promise<void> {
  for (let attempt = 0; attempt < 50; attempt++) {
    if (check()) return;
    await new Promise(resolve => setTimeout(resolve, 10));
  }
}

/** Stops an engine once its sockets have closed, so no close it logs lands after the test that opened them. */
export async function stopWhenDrained(hal: HalServer): Promise<void> {
  await eventually(() => hal.wss.clients.size === 0);
  await hal.stop();
}

/** A store exposing only the required members, so a suite can add, replace or leave out an optional one. */
export function requiredMembersOf(inner: InMemorySessionStore): SessionStore {
  return {
    create: inner.create.bind(inner),
    get: inner.get.bind(inner),
    delete: inner.delete.bind(inner),
    count: inner.count.bind(inner),
    clear: inner.clear.bind(inner),
  };
}
"""
